#pragma once
// Runs the chord converter on its own thread so that the audio thread only copies samples in and takes notes out (no locks, no allocation).
#include <array>
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <thread>
#include <vector>

#include "basic_pitch.h"

#if STRUMLINE_POLY
#include "nmp_model.h"  // generated by CMake from engine/models/nmp.onnx: gm::kNmpModel, gm::kNmpModelSize
#endif

namespace gm {

class PolyWorker {
public:
    ~PolyWorker() { stop(); }

    // Loads the model and starts the thread. False when ONNX Runtime or the model is not there (the plug-in then works as the one-note converter).
    bool start(double hostRate) {
        stop();
#if STRUMLINE_POLY
        if (!poly_.load(kNmpModel, kNmpModelSize, 2)) return false;
        poly_.prepare(hostRate);
        ring_.assign(kRing, 0.0f);
        wr_.store(0);
        rd_ = 0;
        qw_.store(0);
        qr_.store(0);
        resetFlag_.store(false);
        running_.store(true);

        thread_ = std::thread([this] { loop(); });
        return true;
#else
        (void)hostRate;
        return false;
#endif
    }
    void stop() {
#if STRUMLINE_POLY
        if (thread_.joinable()) {
            running_.store(false);
            wake_.notify_one();
            thread_.join();
        }

#endif
    }
    bool running() const { return running_.load(); }

    // Settings, from any thread.
    void setSensitivityDb(float db) { sens_.store(db); }
    void setLookaheadFrames(int f) { look_.store(f); }
    void setActive(bool on) { active_.store(on); }
    void setHopFrames(int f) { hop_.store(f); }
    // Total milliseconds the model has run since the thread started (the editor turns the difference over time into a load figure).
    double busyMs() const { return double(busyUs_.load()) * 0.001; }
    void requestReset() { resetFlag_.store(true); }
    float lastRunMs() const { return runMs_.load(); }

    // Audio thread: the guitar of this block.
    void push(const float* x, int n) {
#if STRUMLINE_POLY
        if (!running_.load(std::memory_order_relaxed) || !active_.load(std::memory_order_relaxed)) return;
        std::size_t w = wr_.load(std::memory_order_relaxed);
        const std::size_t r = rdPublished_.load(std::memory_order_acquire);
        if (w + std::size_t(n) - r > kRing) return;  // the worker is far behind: drop this block rather than wait
        for (int i = 0; i < n; ++i) ring_[(w + std::size_t(i)) & (kRing - 1)] = x[i];
        wr_.store(w + std::size_t(n), std::memory_order_release);
        pending_.store(true, std::memory_order_release);
        wake_.notify_one();  // no lock taken here (this is the audio thread): the flag above keeps the wake-up, the wait has a short timeout
#else
        (void)x; (void)n;
#endif
    }
    // Audio thread: the notes the worker has decided since the last call.
    bool pop(PolyEvent& e) {
        const std::size_t r = qr_.load(std::memory_order_relaxed);
        if (r == qw_.load(std::memory_order_acquire)) return false;
        e = queue_[r & (kQueue - 1)];
        qr_.store(r + 1, std::memory_order_release);
        return true;
    }

private:
    static constexpr std::size_t kRing = 1 << 18, kQueue = 256;

#if STRUMLINE_POLY
    void loop() {
        std::vector<PolyEvent> ev;
        std::vector<float> chunk(1024);
        bool wasActive = true;
        while (running_.load()) {
            {
                std::unique_lock<std::mutex> lock(wakeMutex_);
                // A flag, not only the notification: a wake-up that arrives while the thread is busy must not be lost (that added up to 30 ms of delay and made the
                // chord test miss notes). The short timeout covers the rare race between the check and the wait.
                wake_.wait_for(lock, std::chrono::milliseconds(4), [this] { return pending_.load() || !running_.load(); });
                pending_.store(false);
            }
            const bool active = active_.load();
            if (resetFlag_.exchange(false) || (active && !wasActive)) {
                poly_.reset();
                rd_ = wr_.load(std::memory_order_acquire);
                rdPublished_.store(rd_, std::memory_order_release);
            }
            wasActive = active;
            poly_.setSensitivityDb(sens_.load());
            poly_.setLookaheadFrames(look_.load());
            poly_.setHopFrames(hop_.load());
            for (;;) {
                const std::size_t w = wr_.load(std::memory_order_acquire);
                if (rd_ == w) break;
                const std::size_t n = std::min<std::size_t>(chunk.size(), w - rd_);
                for (std::size_t i = 0; i < n; ++i) chunk[i] = ring_[(rd_ + i) & (kRing - 1)];
                rd_ += n;
                rdPublished_.store(rd_, std::memory_order_release);
                if (!active) continue;
                ev.clear();
                poly_.feed(chunk.data(), int(n), ev);
                if (poly_.runs() != lastRuns_) {
                    lastRuns_ = poly_.runs();
                    runMs_.store(poly_.lastRunMs());
                    busyUs_.fetch_add((long long)(poly_.lastRunMs() * 1000.0f));
                }
                for (const auto& e : ev) {
                    const std::size_t qw = qw_.load(std::memory_order_relaxed);
                    if (qw - qr_.load(std::memory_order_acquire) >= kQueue) break;
                    queue_[qw & (kQueue - 1)] = e;
                    qw_.store(qw + 1, std::memory_order_release);
                }
            }
        }
    }

    PolyTranscriber poly_;
    std::condition_variable wake_;
    std::mutex wakeMutex_;
    std::atomic<bool> pending_{false};
    std::thread thread_;
#endif
    std::vector<float> ring_;
    std::array<PolyEvent, kQueue> queue_{};
    std::atomic<std::size_t> wr_{0}, rdPublished_{0}, qw_{0}, qr_{0};
    std::size_t rd_ = 0;
    std::atomic<bool> running_{false}, active_{true}, resetFlag_{false};
    std::atomic<float> sens_{-54.0f}, runMs_{0.0f};
    std::atomic<int> look_{6}, hop_{3};
    std::atomic<long long> busyUs_{0};
    long long lastRuns_ = 0;
};

}  // namespace gm
